import local.cleartv.mobile.WidgetSigner;
import java.io.*;import java.nio.file.*;import java.security.*;import java.security.cert.*;import java.util.*;import java.util.zip.*;import javax.xml.parsers.*;import javax.xml.crypto.*;import javax.xml.crypto.dsig.*;import javax.xml.crypto.dsig.dom.*;import org.w3c.dom.*;
public class SignerCheck {
 static KeyStore store(Path file,char[] password)throws Exception{KeyStore k=KeyStore.getInstance("PKCS12");try(InputStream in=Files.newInputStream(file)){k.load(in,password);}return k;}
 static String alias(KeyStore s)throws Exception{Enumeration<String> e=s.aliases();while(e.hasMoreElements()){String a=e.nextElement();if(s.isKeyEntry(a))return a;}throw new Exception("Missing key");}
 static List<X509Certificate> chain(KeyStore s,String alias)throws Exception{List<X509Certificate> out=new ArrayList<>();for(java.security.cert.Certificate c:s.getCertificateChain(alias))out.add((X509Certificate)c);return out;}
 public static void main(String[] args)throws Exception{
  Path root=Paths.get(args[0]),tv=root.resolve(".tools/tizen/sdk/data/sdk-data/keystore/samsung/ClearTV20261022");String json=new String(Files.readAllBytes(root.resolve(".tools/tizen/private/clear-tv-signing.json")),"UTF-8");String password=json.replaceAll("(?s).*\"password\"\\s*:\\s*\"([^\"]+)\".*","$1");char[] pass=password.toCharArray();KeyStore a=store(tv.resolve("author.p12"),pass),d=store(tv.resolve("distributor.p12"),pass);String aa=alias(a),dd=alias(d);
  Path source=root.resolve("mobile-app/build/assets/tv-app.zip");ByteArrayOutputStream edited=new ByteArrayOutputStream();try(ZipInputStream in=new ZipInputStream(Files.newInputStream(source));ZipOutputStream out=new ZipOutputStream(edited)){ZipEntry e;byte[] buffer=new byte[8192];while((e=in.getNextEntry())!=null){ByteArrayOutputStream f=new ByteArrayOutputStream();int n;while((n=in.read(buffer))!=-1)f.write(buffer,0,n);byte[] data=f.toByteArray();if(e.getName().equals("config.xml"))data=new String(data,"UTF-8").replace("ClearMob01","ClearTest1").replace("Clear TV Mobile","Clear TV Mobile Test").getBytes("UTF-8");out.putNextEntry(new ZipEntry(e.getName()));out.write(data);out.closeEntry();}}
  byte[] signed=WidgetSigner.build(new ByteArrayInputStream(edited.toByteArray()),"{\"revision\":\"test\",\"settings\":{\"theme\":\"zamalek\",\"customTitle\":\"Mobile signing test\",\"cardWidth\":260}}".getBytes("UTF-8"),(PrivateKey)a.getKey(aa,pass),chain(a,aa),(PrivateKey)d.getKey(dd,pass),chain(d,dd));
  Path output=root.resolve("mobile-app/tests/signed-test.wgt");Files.write(output,signed);Map<String,byte[]> files=new HashMap<>();try(ZipInputStream in=new ZipInputStream(new ByteArrayInputStream(signed))){ZipEntry e;while((e=in.getNextEntry())!=null){ByteArrayOutputStream f=new ByteArrayOutputStream();byte[] buffer=new byte[8192];int n;while((n=in.read(buffer))!=-1)f.write(buffer,0,n);files.put(e.getName(),f.toByteArray());}}
  for(String name:new String[]{"author-signature.xml","signature1.xml"}){DocumentBuilderFactory fac=DocumentBuilderFactory.newInstance();fac.setNamespaceAware(true);Document doc=fac.newDocumentBuilder().parse(new ByteArrayInputStream(files.get(name)));NodeList certs=doc.getElementsByTagNameNS(XMLSignature.XMLNS,"X509Certificate");X509Certificate cert=(X509Certificate)CertificateFactory.getInstance("X.509").generateCertificate(new ByteArrayInputStream(Base64.getMimeDecoder().decode(certs.item(0).getTextContent())));DOMValidateContext ctx=new DOMValidateContext(cert.getPublicKey(),doc.getDocumentElement());ctx.setProperty("org.jcp.xml.dsig.secureValidation",Boolean.FALSE);Element prop=(Element)doc.getElementsByTagNameNS(XMLSignature.XMLNS,"Object").item(0);ctx.setIdAttributeNS(prop,null,"Id");XMLSignatureFactory factory=XMLSignatureFactory.getInstance("DOM");URIDereferencer fallback=factory.getURIDereferencer();ctx.setURIDereferencer((ref,context)->{if(ref.getURI().startsWith("#"))return fallback.dereference(ref,context);return new OctetStreamData(new ByteArrayInputStream(files.get(ref.getURI())));});XMLSignature signature=factory.unmarshalXMLSignature(ctx);if(!signature.validate(ctx)){for(Object r:signature.getSignedInfo().getReferences()){Reference ref=(Reference)r;System.out.println(ref.getURI()+" digest valid="+ref.validate(ctx));}throw new Exception(name+" signature failed");}System.out.println("Verified "+name+" and every referenced file");}
  KeyPair key=WidgetSigner.newKey();Files.write(root.resolve("mobile-app/tests/test.csr"),WidgetSigner.csr(key,"TizenSDK","2.0#AbC+xyz/123=").getBytes("US-ASCII"));System.out.println("Standalone signer check PASS");
 }
}
